package com.google.javascript.jscomp.transpile;

import static com.google.common.truth.Truth.assertThat;
import static com.google.common.truth.Truth.assertWithMessage;

import com.google.common.collect.ImmutableList;
import com.google.javascript.jscomp.bundle.TranspilationException;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.junit.Before;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.junit.runners.JUnit4;

/** Tests for {@link BaseTranspiler}. */
@RunWith(JUnit4.class)
public final class BaseTranspilerTest {

  private Transpiler transpiler;
  private BaseTranspiler.CompilerSupplier compiler;

  FakeCompilerSupplier mockCompiler;

  /** Fake that returns the canned result for the given arguments, like the mock it replaces. */
  private static final class FakeCompilerSupplier extends BaseTranspiler.CompilerSupplier {
    final Map<List<Object>, BaseTranspiler.CompileResult> compileResults = new HashMap<>();
    final Map<String, String> runtimes = new HashMap<>();

    @Override
    public BaseTranspiler.CompileResult compile(String path, String code) {
      return compileResults.get(ImmutableList.of(path, code));
    }

    @Override
    public String runtime(String library) {
      return runtimes.getOrDefault(library, "");
    }
  }

  private static final String FOO_JS = "foo.js";
  private static final String SOURCE_JS = "source.js";

  @Before
  public void setUp() {
    mockCompiler = new FakeCompilerSupplier();
    transpiler = new BaseTranspiler(mockCompiler, "es6_runtime");
    compiler = new BaseTranspiler.CompilerSupplier();
  }

  // Tests for BaseTranspiler

  @Test
  public void testTranspiler_transpile() {
    mockCompiler.compileResults.put(
        ImmutableList.of(FOO_JS, "bar"),
        new BaseTranspiler.CompileResult("result", true, "srcmap"));
    assertThat(transpiler.transpile(FOO_JS, "bar"))
        .isEqualTo(new TranspileResult(FOO_JS, "bar", "result", "srcmap"));
  }

  @Test
  public void testTranspiler_noTranspilation() {
    mockCompiler.compileResults.put(
        ImmutableList.of(FOO_JS, "bar"),
        new BaseTranspiler.CompileResult("result", false, "srcmap"));
    assertThat(transpiler.transpile(FOO_JS, "bar"))
        .isEqualTo(new TranspileResult(FOO_JS, "bar", "bar", ""));
  }

  @Test
  public void testTranspiler_runtime() {
    mockCompiler.runtimes.put("es6_runtime", "$jscomp.es6();");
    assertThat(transpiler.runtime()).isEqualTo("$jscomp.es6();");
  }

  // Tests for CompilerSupplier

  @Test
  public void testCompilerSupplier_compileChanged() {
    BaseTranspiler.CompileResult result = compiler.compile(SOURCE_JS, "const x = () => 42;");
    assertThat(result.source).isEqualTo("var x = function() {\n  return 42;\n};\n");
    assertThat(result.transpiled).isTrue();
    assertThat(result.sourceMap)
        .contains("\"mappings\":\"AAAA,IAAMA,IAAIA,QAAA,EAAM;AAAA,SAAA,EAAA;AAAA,CAAhB;;\"");
  }

  @Test
  public void testCompilerSupplier_compileNoChange() {
    BaseTranspiler.CompileResult result = compiler.compile(SOURCE_JS, "var x = 42;");
    assertThat(result.source).isEqualTo("var x = 42;\n");
    assertThat(result.transpiled).isFalse();
    assertThat(result.sourceMap).isEmpty();
  }

  @Test
  public void testCompilerSupplier_error() {
    try {
      compiler.compile(SOURCE_JS, "cons x = () => 42;");
      assertWithMessage("Expected an exception.").fail();
    } catch (TranspilationException expected) {
    }
  }

  @Test
  public void testCompilerSupplier_runtime() {
    String runtime = compiler.runtime("es6_runtime");
    assertThat(runtime).contains("$jscomp.polyfill(\"Map\"");
    assertThat(runtime).contains("$jscomp.makeIterator");
    assertThat(runtime).contains("$jscomp.inherits");
  }

  @Test
  public void testCompilerSupplier_inlineSourceMap() {
    // This is a source map generated by
    // tsc --inlineSourceMap --inlineSources -t ES2017 source.ts
    // and the content of source.ts is "const x = () => 42".
    BaseTranspiler.CompileResult result =
        compiler.compile(
            SOURCE_JS,
            """
            const x = () => 42;
            //# sourceMappingURL=data:application/json;base64,\
            eyJ2ZXJzaW9uIjozLCJmaWxlIjoic291cmNlLmpzIiwic291cmNlUm9vdCI6IiIsInNvdXJjZXMiOlsi\
            c291cmNlLnRzIl0sIm5hbWVzIjpbXSwibWFwcGluZ3MiOiJBQUFBLE1BQU0sQ0FBQyxHQUFHLEdBQUcs\
            RUFBRSxDQUFDLEVBQUUsQ0FBQyIsInNvdXJjZXNDb250ZW50IjpbImNvbnN0IHggPSAoKSA9PiA0Mjtc\
            biJdfQ==\
            """);
    assertThat(result.source).isEqualTo("var x = function() {\n  return 42;\n};\n");
    assertThat(result.transpiled).isTrue();
    // This should map back to the typescript source file.
    assertThat(result.sourceMap)
        .isEqualTo(
            """
            {
            "version":3,
            "file":"/source.js",
            "lineCount":4,
            "mappings":"AAAA,IAAMA,IAAIA,QAAA,EAAM;AAAA,SAAA,EAAA;AAAA,CAAhB;;",
            "sources":["/source.ts"],
            "sourcesContent":["const x = () => 42;\\n"],
            "names":["x"]
            }
            """);
  }
}
